/* From Uiverse.io by Nawsome - Tags: loader */
.__UIV_SCOPE__ .socket {
  width: 200px;
  height: 200px;
  position: absolute;
  left: 50%;
  margin-left: -100px;
  top: 50%;
  margin-top: -100px;
}

.__UIV_SCOPE__ .hex-brick {
  background: #000000;
  width: 30px;
  height: 17px;
  position: absolute;
  top: 5px;
  animation-name: fade00;
  animation-duration: 2s;
  animation-iteration-count: infinite;
  -webkit-animation-name: fade00;
  -webkit-animation-duration: 2s;
  -webkit-animation-iteration-count: infinite;
}

.__UIV_SCOPE__ .h2 {
  transform: rotate(60deg);
  -webkit-transform: rotate(60deg);
}

.__UIV_SCOPE__ .h3 {
  transform: rotate(-60deg);
  -webkit-transform: rotate(-60deg);
}

.__UIV_SCOPE__ .gel {
  height: 30px;
  width: 30px;
  transition: all .3s;
  -webkit-transition: all .3s;
  position: absolute;
  top: 50%;
  left: 50%;
}

.__UIV_SCOPE__ .center-gel {
  margin-left: -15px;
  margin-top: -15px;
  animation-name: pulse00;
  animation-duration: 2s;
  animation-iteration-count: infinite;
  -webkit-animation-name: pulse00;
  -webkit-animation-duration: 2s;
  -webkit-animation-iteration-count: infinite;
}

